import{_ as s,c as t,o as l,j as e,a as n}from"./chunks/framework.BKeRpnBD.js";const m=JSON.parse('{"title":"乾下兑上 夬：","description":"京氏易传 - 乾下兑上 夬：","frontmatter":{"title":"乾下兑上 夬：","description":"京氏易传 - 乾下兑上 夬："},"headers":[],"relativePath":"zh/classics/jingshi/039.md","filePath":"zh/classics/jingshi/039.md"}'),i={name:"zh/classics/jingshi/039.md"};function r(c,a,o,p,d,h){return l(),t("div",null,[...a[0]||(a[0]=[e("h1",{id:"乾下兑上-夬",tabindex:"-1"},[n("乾下兑上 夬： "),e("a",{class:"header-anchor",href:"#乾下兑上-夬","aria-label":"Permalink to “乾下兑上 夬：”"},"​")],-1),e("p",null,"刚决柔，阴道灭。五阳务下，一阴危上，将反游魂。九四，悔也。",-1),e("p",null,"泽上于天，君道行也。【夬，五世。六位周而复始，为游魂。至九四成阴，入坎为需。】与兑为飞伏。【丁酉金，癸亥水。】九五立世，九二大夫为应。【九五在兑象为世，泽小于天也。】",-1),e("p",null,"建始己亥至甲辰，【小雪，清明。】积算起甲辰至癸卯，周而复始。金木分乾兑入坤象。【入坤宫起积算。】",-1),e("p",null,"五星从位起太阴，【太阴，水星。入卦起算。】亢宿从位降丁酉，【二十八宿配亢宿，入夬卦丁酉金上起。】分气候二十八。【积算起宫二十八，入卦中甲辰，还丁酉金上定吉凶。】",-1),e("p",null,"《易》云：“泽上于天，夬”。“扬于王庭”。柔道消，消不可极，反于游魂。九四柔来文刚，阴道存也，阴之道不可终否。刚柔相济，日月明矣；天地定位，人事通也。【凡卦，阴极阳生，阳极阴生，生生之义，不绝之貌。日月循环，天地交泰，阴阳相荡，六位交分，万物生焉。】故曰：雷动风行，山泽通气。人之运动，体斯合矣。【人禀五常，三焦九窍，风火逓（递）相兼济，以一位亏，四体羸焉。】",-1),e("p",null,"阴阳升降，反复道也。次降入游魂水天需卦。",-1)])])}const _=s(i,[["render",r]]);export{m as __pageData,_ as default};
